// Web form -> rows. The niche is required; keywords are optional (typed and/or a CSV with columns niche, keyword,
// audience, country: one upload can plan several niches). Questions left empty are filled from Defaults.
const f = $input.first();
const j = f.json;
const get = (...names) => { for (const n of names) if (j[n] !== undefined && j[n] !== '') return j[n]; return ''; };
const TIME = { 'Last 7 days': 'now 7-d', 'Last 30 days': 'today 1-m', 'Last 3 months': 'today 3-m', 'Last 12 months': 'today 12-m' };
const timeOf = v => { const k = Object.keys(TIME).find(t => String(v || '').startsWith(t)); return k ? TIME[k] : null; };
// "Worldwide" = '' (explicit); nothing chosen = null (Defaults); "India (IN)" or "IN" = the code
const countryOf = v => { const s = String(v || '').trim(); if (!s) return null; if (/^worldwide$/i.test(s)) return '';
  const m = s.match(/\(([A-Z]{2})\)\s*$/); return m ? m[1] : (/^[A-Za-z]{2}$/.test(s) ? s.toUpperCase() : null); };
const formats = [].concat(get('formats', 'Where do you want to post?') || []).join(', ').toLowerCase() || null;
const base = {
  niche: String(get('niche', 'What do you want to make content about?')).trim(),
  audience: String(get('audience', 'Who do you want to reach?')).trim(),
  country: countryOf(get('country', 'Where do you want to reach people?')),
  timeRange: timeOf(get('timeRange', 'How recent should the trends be?')),
  formats, useAI: null, source: 'form',
};
const rows = String(get('keywords', 'Any specific topics you want to cover?')).split(/[\n,;]+/).map(k => k.trim())
  .filter(Boolean).map(keyword => ({ ...base, keyword }));

// optional CSV upload
const file = Object.keys(f.binary || {})[0];
if (file) {
  const text = (await this.helpers.getBinaryDataBuffer(0, file)).toString('utf8').replace(/^﻿/, '');
  const lines = text.split(/\r?\n/).filter(l => l.trim());
  const sep = (lines[0].match(/;/g) || []).length > (lines[0].match(/,/g) || []).length ? ';' : ',';
  const cells = l => { const out = []; let cur = '', q = false;
    for (let i = 0; i < l.length; i++) { const c = l[i];
      if (q) { if (c === '"' && l[i + 1] === '"') { cur += '"'; i++; } else if (c === '"') q = false; else cur += c; }
      else if (c === '"') q = true; else if (c === sep) { out.push(cur); cur = ''; } else cur += c; }
    out.push(cur); return out.map(x => x.trim()); };
  const head = cells(lines[0]).map(h => h.toLowerCase());
  const col = names => head.findIndex(h => names.includes(h));
  const ki = col(['keyword', 'keywords', 'search term', 'term', 'query']);
  const ni = col(['niche', 'topic', 'group']), ai = col(['audience']), ci = col(['country', 'geo']);
  if (ki < 0 && ni < 0) throw new Error('The CSV needs a "niche" or a "keyword" column (optional: audience, country).');
  for (const l of lines.slice(1)) {
    const c = cells(l);
    const keyword = ki >= 0 ? c[ki] || '' : '';
    const niche = (ni >= 0 && c[ni]) || base.niche;
    if (!keyword && !(ni >= 0 && c[ni])) continue;
    rows.push({ ...base, keyword, niche,
      audience: (ai >= 0 && c[ai]) || base.audience,
      country: ci >= 0 && c[ci] ? countryOf(c[ci]) ?? base.country : base.country });
  }
}
// just a niche: AI suggests keywords for it (or, without AI, the niche itself is searched)
if (!rows.length) rows.push({ ...base, keyword: '' });
return rows.map(json => ({ json }));

// Google Sheet -> rows. Columns (any order, any case):
//   niche (required) · keyword (leave empty to let AI suggest keywords for that niche) · audience · country ·
//   formats (where you publish) · active ("no" pauses the row)
// Rows without a niche are skipped and reported in the summary.
const rows = [], skipped = [];
for (const { json: r } of $input.all()) {
  const row = Object.fromEntries(Object.entries(r).map(([k, v]) => [String(k).trim().toLowerCase(), String(v ?? '').trim()]));
  const keyword = row.keyword || row.keywords || row.term || '';
  if (!keyword && !row.niche) continue; // an empty line
  if (/^(no|false|0|off|paused)$/i.test(row.active || '')) continue;
  if (!row.niche) { skipped.push(keyword); continue; }
  // null = not given here: filled from Defaults
  rows.push({ keyword, niche: row.niche, audience: row.audience || '', country: row.country ? row.country.toUpperCase() : null,
    timeRange: null, formats: row.formats || row['publish on'] || row.platforms || null, useAI: null, source: 'sheet', skipped });
}
if (!rows.length) throw new Error('No usable rows in the keyword sheet: it needs a "niche" column (and keywords, or AI on).');
return rows.map(json => ({ json }));

// "Run it now" test input -> rows (keywords optional, like the form).
const m = $input.first().json;
const base = { niche: m.niche, audience: m.audience || '', country: m.country == null ? null : String(m.country).toUpperCase(),
  timeRange: null, formats: null, useAI: null, source: 'manual' };
const keywords = String(m.keywords || '').split(/[\n,;]+/).map(k => k.trim()).filter(Boolean);
return (keywords.length ? keywords : ['']).map(keyword => ({ json: { ...base, keyword } }));

// Rows -> one item per niche (+ country + time range) with its keywords. What an input didn't give (null) comes from
// Defaults; an explicit value (even "worldwide" = '') is kept. A niche with few keywords is marked for AI suggestions.
const d = $('Defaults').first().json;
const useAIDefault = d.useAI === true;
const suggestBelow = Number(d.suggestKeywordsBelow ?? 3);
const rows = $input.all().map(({ json: r }) => ({ ...r,
  keyword: String(r.keyword || '').trim(),
  country: r.country ?? d.defaultCountry ?? '',
  timeRange: r.timeRange ?? d.defaultTimeRange,
  formats: r.formats || d.defaultFormats,
  useAI: r.useAI ?? useAIDefault }));
const groups = new Map();
for (const r of rows) {
  if (!r.niche) throw new Error(`"${r.keyword}" has no niche. Every keyword needs a niche (what you make content about).`);
  const group = `${r.niche.toLowerCase()}|${r.country}|${r.timeRange}`;
  const g = groups.get(group) ?? { group, niche: r.niche, audience: '', country: r.country, timeRange: r.timeRange,
    formats: new Set(), useAI: r.useAI, source: r.source, skipped: r.skipped || [], keywords: [] };
  if (!g.audience && r.audience) g.audience = r.audience;
  String(r.formats).split(',').map(s => s.trim()).filter(Boolean).forEach(x => g.formats.add(x));
  if (r.keyword && !g.keywords.some(k => k.toLowerCase() === r.keyword.toLowerCase())) g.keywords.push(r.keyword);
  groups.set(group, g);
}
const max = Number(d.maxKeywordsPerRun) || 300;
const total = [...groups.values()].reduce((s, g) => s + g.keywords.length, 0);
if (total > max) throw new Error(`This run has ${total} keywords; the limit is ${max} (maxKeywordsPerRun in Defaults).`);
return [...groups.values()].map((g, i) => {
  const out = { ...g, id: `K${i + 1}`, formats: [...g.formats].join(', '), suggested: [], keywordNote: '',
    needsKeywords: g.useAI && g.keywords.length < suggestBelow };
  if (!out.needsKeywords && !g.keywords.length) {
    // without AI, a niche with no keywords is searched as written; that finds little, so say so
    out.keywords = [g.niche];
    out.keywordNote = "You didn't add any topics, so we searched your niche as written. Add 3-5 specific topics "
      + '(products, ingredients, tools, common problems) for much better ideas.';
  }
  return { json: out };
});

// Few or no keywords: ask the AI for searchable ones. People describe a niche ("ai product roadmap") differently from
// how they search it ("cursor", "vibe coding"); described phrases have almost no Google data, so the rules matter.
const d = $('Defaults').first().json;
const want = Math.max(3, Number(d.suggestedKeywords) || 8);
return $input.all().map(({ json: g }) => ({ json: { ...g, prompt: [
  `I make content about: ${g.niche}.`,
  g.audience ? `My audience: ${g.audience}.` : null,
  `Country: ${g.country || 'worldwide'}.`,
  g.keywords.length ? `Keywords I already track: ${g.keywords.join(', ')}.` : null,
  ``,
  `Suggest ${want} keywords to track on Google Trends for this niche. Each one must be:`,
  `- something my audience actually types into Google: 1 to 3 words in plain search language, like "retinol", "walking pad" or "steam wishlist";`,
  `- a specific part of the niche: a product or brand, an ingredient or tool, a technique, or a common problem;`,
  `- searched often enough to have Google data in this country;`,
  `- not a description of the niche (like "ai product roadmap" or "beginner skincare tips"), not my niche name, and not one of my keywords.`,
  `Mix them: some core topics, some popular products or brands, some problems people search for.`,
  ``,
  `Set "nicheId" to "${g.id}".`,
].filter(l => l !== null).join('\n') } }));

// The AI's suggestions, added to the niche's keywords (matched back by the id it echoes).
const d = $('Defaults').first().json;
const want = Math.max(3, Number(d.suggestedKeywords) || 8);
const asked = $('Ask for keyword ideas').all().map(p => p.json);
const clean = k => String(k || '').trim().replace(/^["'“”]+|["'“”.]+$/g, '').replace(/\s+/g, ' ').toLowerCase();
return $input.all().map((item, i) => {
  const out = item.json.output || {};
  const g = asked.find(p => p.id === out.nicheId) ?? asked[item.pairedItem?.item] ?? asked[i];
  const have = new Set([...g.keywords.map(k => k.toLowerCase()), g.niche.toLowerCase()]);
  const suggested = [...new Set((out.keywords || []).map(clean))]
    .filter(k => k && k.split(' ').length <= 4 && !have.has(k)).slice(0, want);
  const { prompt, ...rest } = g;
  const keywords = [...g.keywords, ...suggested];
  return { json: { ...rest, keywords: keywords.length ? keywords : [g.niche], suggested,
    keywordNote: keywords.length ? '' : "We couldn't find topics to suggest, so we searched your niche as written." } };
});

const reasonFor = error => { const raw = String(error?.message || error || 'unknown error');
  return /402|payment|credit|billing|prepay|exhausted/i.test(raw) ? 'the AI account is out of credit'
    : /bad request|api key|401|403|permission|credential/i.test(raw) ? 'the AI key or model name needs checking'
    : /429|quota|rate/i.test(raw) ? 'the AI service is busy, try again soon' : raw.slice(0, 120); };

// Keyword suggestions failed: carry on with what the user gave (or the niche name), and say why.
return $input.all().map(item => {
  const { prompt, error, ...g } = item.json;
  const used = g.keywords.length ? 'only used the topics you gave' : 'searched your niche as written';
  return { json: { ...g, keywords: g.keywords.length ? g.keywords : [g.niche],
    keywordNote: `We couldn't suggest topics this time (${reasonFor(error)}), so we ${used}. `
      + 'Add 3-5 specific topics (products, ingredients, tools, common problems) for better ideas.' } };
});

// Niches -> Google Trends jobs, in chunks of 40 keywords so each call stays short.
const CHUNK = 40;
const jobs = [];
for (const { json: g } of $input.all()) {
  const { needsKeywords, ...niche } = g;
  for (let i = 0; i < g.keywords.length; i += CHUNK)
    jobs.push({ ...niche, keywordsUsed: g.keywords, keywords: g.keywords.slice(i, i + CHUNK) });
}
return jobs.map(json => ({ json }));

// One job -> the Google Trends Actor's input.
const d = $('Defaults').first().json;
const job = $input.first().json;
return [{ json: { ...job, actorInput: {
  keywords: job.keywords,
  preset: 'custom',
  components: d.includeTopics === false ? ['relatedQueries'] : ['relatedQueries', 'relatedTopics'],
  geo: job.country || '',  // empty = worldwide
  timeRange: job.timeRange,
  maxTopicsWaitMinutes: 3, // keeps runs short; topics Google holds back longer are skipped (and not charged)
} } }];

// One job's Google Trends results -> one row per rising search or topic, tagged with the job.
// Keywords Google has no data for are kept as "noData" rows, so the summary can name them.
const job = $('Loop over jobs').first().json;
const tag = { group: job.group, niche: job.niche, audience: job.audience, country: job.country, timeRange: job.timeRange,
  formats: job.formats, useAI: job.useAI, source: job.source, skipped: job.skipped,
  keywordsUsed: job.keywordsUsed, suggested: job.suggested, keywordNote: job.keywordNote };
const growthNumber = g => /breakout/i.test(g || '') ? 5000 : (parseInt(String(g || '').replace(/[^0-9]/g, ''), 10) || 0);
const rows = [];
for (const { json: k } of $input.all()) {
  if (!['complete', 'partial'].includes(k.status)) { rows.push({ ...tag, noData: true, seed: k.keyword }); continue; }
  for (const q of k.relatedQueries?.rising || [])
    rows.push({ ...tag, seed: k.keyword, kind: 'search', text: q.query, topicType: '', growth: q.growth || '', growthNumber: growthNumber(q.growth) });
  for (const t of k.relatedTopics?.rising || [])
    rows.push({ ...tag, seed: k.keyword, kind: 'topic', text: t.title, topicType: /^topic$/i.test(t.type || '') ? '' : (t.type || ''), growth: t.growth || '', growthNumber: growthNumber(t.growth) });
}
return (rows.length ? rows : [{ ...tag, noData: true, seed: '' }]).map(json => ({ json }));

// All jobs' rising searches -> one item per niche with its best candidates. Per niche:
//  1. Junk out. Google Trends data carries bot and AI-agent traffic: prompt-like searches ("explain what X is and its
//     main benefits") and generic Breakouts ("how to make sushi") under unrelated keywords.
//  2. Relevance. With AI, the model judges it later; without AI, a search must share a real word with its keyword or niche.
//  3. Variants merged ("trader joe's retinol" = "trader joes retinol"; a topic and a search naming the same product).
//  4. Ranked by growth, boosted when rising under several keywords or as both a search and a topic; a search that is
//     just your keyword again ranks lower.
//  5. Scheduled runs remember what was sent (8 weeks) and flag what's new since the last run.
//  6. Spread across keywords; with AI, unrelated-looking searches get at most a third of the list (new brands often
//     share no word with your keywords, so the AI gets a chance to keep them).
const d = $('Defaults').first().json;
const limit = Math.max(1, Number(d.ideasPerNiche) || 10);

// ---- tuning (safe to change) ----
const STOP = new Set(['for', 'the', 'and', 'with', 'from', 'that', 'this', 'your', 'you', 'how', 'what', 'when', 'why',
  'who', 'which', 'can', 'does', 'best', 'top', 'near', 'are', 'was', 'use', 'using', 'new', 'free', 'good', 'get', 'not',
  'all', 'about', 'into', 'like', 'more', 'most', 'make', 'way', 'ways', 'vs', 'review', 'reviews', 'usa', 'online']);
const PROMPT_START = /^(explain|describe|write|list|give me|tell me|summarize|summarise|compare|create|generate|provide|act as)\b/i;
const PROMPT_PHRASE = /\band (its|their) (main|primary|key|potential)\b|\bwhy do you think\b|\bin (simple|detail|bullet)/i;
const MAX_WORDS = 15;          // longer "searches" read like prompts; real questions and product names stay under it
const ECHO_FACTOR = 0.3;       // a search that is just your keyword again ("AI agent" under "ai agents") says little
const JUNK_UNDER_KEYWORDS = 3; // the same unrelated search under this many keywords = bot junk
const BOOST_PER_EXTRA_KEYWORD = 0.5, BOOST_SEARCH_AND_TOPIC = 0.2, NOT_NEW_FACTOR = 0.8;
const REMEMBER_WEEKS = 8;

const norm = t => String(t).toLowerCase().replace(/['’]/g, '').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const words = t => norm(t).split(' ').filter(w => w.length > 2 && !STOP.has(w));
const stems = t => new Set(words(t).map(w => w.slice(0, 5)));
const shares = (a, b) => [...a].some(x => b.has(x));
const sig = t => [...new Set(words(t).map(w => w.replace(/(?<=..)s$/, '')))].sort().join(' ') || norm(t);
const allStems = t => new Set(norm(t).split(' ').filter(w => w.length > 1).map(w => w.slice(0, 5)));
const echoes = (text, seed) => { const a = allStems(text), b = allStems(seed); return a.size > 0 && [...a].every(x => b.has(x)); };

const byNiche = {};
for (const { json: r } of $input.all()) (byNiche[r.group] ??= []).push(r);
const memory = $getWorkflowStaticData('global');
memory.sent ??= {}; memory.lastRun ??= {};
const now = Date.now();
const out = [];

for (const [group, rowsAll] of Object.entries(byNiche)) {
  const info = rowsAll[0];
  const useAI = info.useAI === true;
  const remember = info.source === 'sheet'; // one-off form runs always show everything
  const candidates = useAI ? Math.min(limit * 4, 40) : limit; // the AI is strict, so it gets plenty to choose from
  const all = rowsAll.filter(r => !r.noData);
  const seedsWithData = new Set(all.map(r => r.seed));
  const noData = [...new Set(rowsAll.filter(r => r.noData && r.seed).map(r => r.seed))].filter(k => !seedsWithData.has(k));
  const stats = { risingFound: all.length, junk: 0, offTopic: 0, merged: 0, alreadySent: 0, keywordsWithoutData: noData,
    skippedRows: info.skipped || [] };
  // the niche's own words: its name and all its keywords (not the audience: "people", "work", "training" match too much)
  const nicheStems = stems([info.niche, ...seedsWithData].join(' '));

  // 1 + 2
  const under = {};
  for (const r of all) (under[norm(r.text)] ??= new Set()).add(r.seed);
  const kept = all.filter(r => {
    r.related = shares(stems(r.text), nicheStems);
    const promptLike = r.kind === 'search' && (PROMPT_START.test(r.text) || PROMPT_PHRASE.test(r.text)
      || norm(r.text).split(' ').length > MAX_WORDS);
    if (promptLike || (under[norm(r.text)].size >= JUNK_UNDER_KEYWORDS && !r.related)) { stats.junk++; return false; }
    if (!useAI && !r.related) { stats.offTopic++; return false; }
    return true;
  });

  // seed health: how many usable rising searches each keyword brought (a keyword is a seed; Google reports what rises
  // around it, so a good seed is a core topic people search all the time, not something that must be booming itself)
  const keywordYield = {};
  for (const r of kept) keywordYield[r.seed] = (keywordYield[r.seed] || 0) + 1;

  // 3
  const groups = [];
  for (const r of kept.sort((a, b) => b.growthNumber - a.growthNumber)) {
    const g = groups.find(g => g.sig === sig(r.text));
    if (g) {
      stats.merged++;
      g.seeds.add(r.seed); g.kinds.add(r.kind); g.related ||= r.related;
      if (norm(r.text) !== norm(g.text)) g.variants.add(r.text);
      g.topicType ||= r.topicType;
    } else {
      groups.push({ sig: sig(r.text), wordSet: new Set(sig(r.text).split(' ')), text: r.text, growth: r.growth,
        growthNumber: r.growthNumber, topicType: r.topicType, related: r.related, echo: [...seedsWithData, info.niche].some(k => echoes(r.text, k)),
        seeds: new Set([r.seed]), kinds: new Set([r.kind]), variants: new Set() });
    }
  }
  for (const t of groups.filter(g => g.kinds.size === 1 && g.kinds.has('topic') && g.wordSet.size >= 3)) {
    const q = groups.find(g => g !== t && g.kinds.has('search') && [...t.seeds].some(k => g.seeds.has(k))
      && [...t.wordSet].every(w => g.wordSet.has(w)));
    if (!q) continue;
    stats.merged++;
    q.kinds.add('topic'); q.variants.add(t.text); q.topicType ||= t.topicType;
    q.growthNumber = Math.max(q.growthNumber, t.growthNumber);
    t.mergedInto = q;
  }
  const merged = groups.filter(g => !g.mergedInto);

  // 4 + 5
  const sent = remember ? (memory.sent[group] ??= {}) : {};
  for (const [k, t] of Object.entries(sent)) if (now - t > REMEMBER_WEEKS * 7 * 86400e3) delete sent[k];
  const lastRun = new Set(remember ? memory.lastRun[group] || [] : []);
  if (remember) memory.lastRun[group] = merged.map(g => g.sig);
  const scored = merged
    .filter(g => { if (sent[g.sig]) { stats.alreadySent++; return false; } return true; })
    .map(g => {
      const isNew = remember ? !lastRun.has(g.sig) : null;
      const score = g.growthNumber * (1 + BOOST_PER_EXTRA_KEYWORD * (g.seeds.size - 1))
        * (g.kinds.size > 1 ? 1 + BOOST_SEARCH_AND_TOPIC : 1) * (isNew === false ? NOT_NEW_FACTOR : 1)
        * (g.echo ? ECHO_FACTOR : 1);
      return { ...g, isNew, score };
    })
    .sort((a, b) => b.score - a.score);

  // 6
  const perSeed = Math.max(2, Math.ceil(candidates / Math.max(1, seedsWithData.size)));
  const used = {}, picked = [];
  const take = (list, max) => { for (const g of list) {
    if (picked.length >= max) return;
    if (picked.includes(g)) continue;
    const main = [...g.seeds][0];
    if ((used[main] || 0) < perSeed) { used[main] = (used[main] || 0) + 1; picked.push(g); } } };
  const related = scored.filter(g => g.related), unrelated = scored.filter(g => !g.related);
  take(related, useAI ? candidates - Math.ceil(candidates / 3) : candidates);
  take(unrelated, candidates);
  take(related, candidates);

  const geo = encodeURIComponent(info.country || ''), date = encodeURIComponent(info.timeRange);
  out.push({ id: `N${out.length + 1}`, group, niche: info.niche, audience: info.audience, formats: info.formats, country: info.country,
    timeRange: info.timeRange, useAI, source: info.source, stats, nothingNew: picked.length === 0,
    keywordsUsed: info.keywordsUsed || [...seedsWithData], suggested: info.suggested || [], keywordNote: info.keywordNote || '',
    keywordYield,
    candidates: picked.map((g, i) => ({ n: i + 1, key: g.sig, text: g.text, variants: [...g.variants], related: g.related, echo: g.echo,
      kind: [...g.kinds].sort().join(' + '), topicType: g.topicType, growth: g.growth, seeds: [...g.seeds], isNew: g.isNew,
      googleTrends: `https://trends.google.com/trends/explore?q=${encodeURIComponent(g.text)}&geo=${geo}&date=${date}` })) });
}
return out.map(json => ({ json }));

// The AI's ideas, matched back to their searches; keeps the relevant ones (minRelevance in Defaults), best first.
const d = $('Defaults').first().json;
const minRelevance = Number(d.minRelevance) || 6;
const limit = Math.max(1, Number(d.ideasPerNiche) || 10);
// The chain's answer doesn't carry the niche it belongs to, so each niche has an id the AI echoes back ("nicheId");
// n8n's item link and the position are fallbacks.
const prepared = $('Prepare AI request').all().map(p => p.json);
return $input.all().map((item, i) => {
  const out = item.json.output || {};
  const n = prepared.find(p => p.id === out.nicheId) ?? prepared[item.pairedItem?.item] ?? prepared[i];
  const byN = Object.fromEntries((out.ideas || []).map(x => [Number(x.n), x]));
  // a search that is just your keyword again tells little about what people want: capped at 5, whatever the AI said
  const scored = n.candidates.map(c => ({ c, a: byN[c.n] && { ...byN[c.n],
    relevance: c.echo ? Math.min(Number(byN[c.n].relevance), 5) : Number(byN[c.n].relevance) } }));
  const relevant = scored.filter(({ a }) => a && Number(a.relevance) >= minRelevance && a.title);
  const keep = [...relevant].sort((x, y) => y.a.relevance - x.a.relevance || x.c.n - y.c.n).slice(0, limit);
  const { prompt, ...rest } = n;
  // aiDropped: judged off-topic or weak; the rest of the list was just past ideasPerNiche
  return { json: { ...rest, mode: 'ideas', aiDropped: scored.length - relevant.length,
    ideas: keep.map(({ c, a }) => ({ ...c, idea: a.title, angle: a.angle || '', hook: a.hook || '', format: a.format || '',
      whyRising: a.whyRising || '', checkBeforePublishing: a.checkBeforePublishing || [], relevance: Number(a.relevance) })) } };
});

const reasonFor = error => { const raw = String(error?.message || error || 'unknown error');
  return /402|payment|credit|billing|prepay|exhausted/i.test(raw) ? 'the AI account is out of credit'
    : /bad request|api key|401|403|permission|credential/i.test(raw) ? 'the AI key or model name needs checking'
    : /429|quota|rate/i.test(raw) ? 'the AI service is busy, try again soon' : raw.slice(0, 120); };

// The AI call failed (bad key, no credit, rate limit, outage): deliver the rising searches report instead of nothing.
// n8n's error output carries the niche's own data, plus the error.
return $input.all().map(item => {
  const { prompt, error, ...n } = item.json;
  return { json: { ...n, mode: 'report',
    aiNote: `We couldn't write ideas this time (${reasonFor(error)}), so here are the rising searches instead.` } };
});

// Every niche -> its rows in one fixed set of columns (the same for ideas and for the report), plus a summary line.
// Scheduled runs also remember what was sent, so next week brings only new searches.
const d = $('Defaults').first().json;
const limit = Math.max(1, Number(d.ideasPerNiche) || 10);
const memory = $getWorkflowStaticData('global');
memory.sent ??= {};
const today = new Date().toISOString().slice(0, 10);
const COLUMNS = ['date', 'niche', 'mode', 'status', 'idea', 'angle', 'hook', 'format', 'whyRising', 'checkBeforePublishing',
  'risingSearch', 'growth', 'type', 'alsoSearchedAs', 'newThisWeek', 'yourKeywords', 'relevance', 'googleTrends', 'note'];
const row = (n, c, extra) => Object.fromEntries(COLUMNS.map(k => [k, ({
  date: today, niche: n.niche, status: 'to review', risingSearch: c.text, growth: c.growth,
  type: c.kind + (c.topicType ? ` (${c.topicType})` : ''), alsoSearchedAs: c.variants.join('; '),
  newThisWeek: c.isNew === null ? '' : c.isNew ? 'yes' : 'no', yourKeywords: c.seeds.join(', '), googleTrends: c.googleTrends,
  ...extra })[k] ?? '']));

return $input.all().map(({ json: n }) => {
  const mode = n.nothingNew ? 'nothing new' : n.mode || (n.useAI ? 'ideas' : 'report');
  let rows = [];
  if (mode === 'ideas') rows = n.ideas.map(c => row(n, c, { mode, idea: c.idea, angle: c.angle, hook: c.hook, format: c.format,
    whyRising: c.whyRising, checkBeforePublishing: (c.checkBeforePublishing || []).join('; '), relevance: c.relevance }));
  // the report prefers word-matched searches: when the AI failed, its list also holds unrelated ones it was meant to judge
  const matched = n.candidates.filter(c => c.related);
  const reportPicks = (matched.length ? matched : n.candidates).slice(0, limit);
  if (mode === 'report') rows = reportPicks.map(c => row(n, c, { mode, note: n.aiNote || '' }));
  if (n.source === 'sheet') { memory.sent[n.group] ??= {};
    for (const c of mode === 'ideas' ? n.ideas : mode === 'report' ? reportPicks : []) memory.sent[n.group][c.key] = Date.now(); }
  const st = n.stats;
  // off-topic: dropped by the word match, judged weak by the AI, or (AI unavailable) left out of the report as unrelated
  const offTopic = st.offTopic + (n.aiDropped || 0) + (mode === 'report' && matched.length ? n.candidates.length - matched.length : 0);
  // which topics (keywords) were searched, so people learn what works and can keep the good suggestions
  const suggested = n.suggested || [];
  const keywords = { used: n.keywordsUsed || [], suggested, noData: st.keywordsWithoutData, yield: n.keywordYield || {} };
  // the summary says what the person got and what to do, not how it was filtered (that stays in `filtering`)
  const headline = mode === 'nothing new' ? (st.alreadySent ? 'nothing new is rising right now; what is rising was sent before'
      : 'nothing new is rising right now')
    : mode === 'ideas' ? `${rows.length} content ideas, picked from ${st.risingFound} rising searches`
    : `${rows.length} rising searches worth a look, out of ${st.risingFound}`;
  const alreadySent = mode !== 'nothing new' && st.alreadySent ? ` ${st.alreadySent} you got before are left out.` : '';
  const noData = st.keywordsWithoutData.length ? ` Not enough Google data for: ${st.keywordsWithoutData.join(', ')}.` : '';
  const suggestedNote = suggested.length ? ` Topics we suggested: ${suggested.join(', ')}.` : '';
  const noDataAtAll = !st.risingFound && keywords.used.length && st.keywordsWithoutData.length >= keywords.used.length;
  const summary = noDataAtAll ? `${n.niche}: not enough Google data for ${keywords.used.join(', ')}.`
    : `${n.niche}: ${headline}.${alreadySent}${noData}${suggestedNote}`;
  const filtering = { risingSearches: st.risingFound, junk: st.junk, offTopic, variantsMerged: st.merged, alreadySent: st.alreadySent };
  return { json: { niche: n.niche, source: n.source, mode, rows, skippedRows: st.skippedRows, keywords,
    keywordNote: n.keywordNote, summary, filtering } };
});

// The results as a web page for the form.
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const niches = $input.all().map(i => i.json);
const card = r => r.mode === 'ideas'
  ? `<div class="card"><div class="t">${esc(r.idea)}</div>
      <div class="m">${esc(r.risingSearch)} · <b>${esc(r.growth)}</b> · ${esc(r.format)} · relevance ${esc(r.relevance)}/10</div>
      <p><b>Hook:</b> ${esc(r.hook)}</p><p><b>Angle:</b> ${esc(r.angle)}</p>
      ${r.whyRising ? `<p><b>Likely why:</b> ${esc(r.whyRising)}</p>` : ''}
      ${r.checkBeforePublishing ? `<p class="chk"><b>Check before publishing:</b> ${esc(r.checkBeforePublishing)}</p>` : ''}
      <a href="${esc(r.googleTrends)}" target="_blank">See it on Google Trends</a></div>`
  : `<tr><td><a href="${esc(r.googleTrends)}" target="_blank">${esc(r.risingSearch)}</a></td><td>${esc(r.growth)}</td>
      <td>${esc(r.type)}</td><td>${esc(r.yourKeywords)}</td></tr>`;
// the topics looked at, each with the rising searches it found: our suggestions marked, no-data ones crossed out
const kw = n => { const k = n.keywords || {}; const sug = new Set(k.suggested || []), none = new Set(k.noData || []);
  return (k.used || []).map(w => none.has(w) ? `<s>${esc(w)}</s>`
    : `${esc(w)}${sug.has(w) ? '*' : ''} (${(k.yield || {})[w] || 0})`).join(', '); };
const section = n => `<h2>${esc(n.niche)}</h2>`
  + `<p class="s">${esc(n.summary.replace(/^[^:]*:\s*/, '').replace(/ Topics we suggested: .*$/, ''))}</p>`
  + `<p class="k">Topics we looked at, with the rising searches each one found: ${kw(n)}`
  + `${(n.keywords?.suggested || []).length ? ' · * our suggestion, keep the ones you like' : ''}`
  + `${(n.keywords?.noData || []).length ? ' · crossed out: not enough Google data' : ''}</p>`
  + (n.keywordNote ? `<p class="chk">${esc(n.keywordNote)}</p>` : '')
  + (n.mode === 'ideas' ? n.rows.map(card).join('')
    : n.mode === 'report' ? `${n.rows[0]?.note ? `<p class="chk">${esc(n.rows[0].note)}</p>` : ''}<table><tr><th>Rising search</th><th>Growth</th><th>Type</th><th>From topic</th></tr>${n.rows.map(card).join('')}</table>`
    : '');
const html = `<style>body{font-family:system-ui,sans-serif}h2{margin:24px 0 4px}.s{color:#555;margin:0 0 4px}.k{color:#777;font-size:13px;margin:0 0 12px}
.card{border:1px solid #ddd;border-radius:10px;padding:12px 14px;margin:10px 0;text-align:left}.t{font-weight:600;font-size:16px}
.m{color:#666;font-size:13px;margin:4px 0 8px}p{margin:6px 0;font-size:14px}.chk{color:#8a5a00}table{border-collapse:collapse;width:100%;font-size:14px}
td,th{border-bottom:1px solid #eee;padding:6px;text-align:left}</style>${niches.map(section).join('')}`;
return [{ json: { html } }];

// A short message for Slack or Telegram covering every niche in this run.
const niches = $input.all().map(i => i.json);
const blocks = niches.map(n => {
  const top = n.mode === 'ideas' ? n.rows.slice(0, 5).map((r, i) => `${i + 1}. ${r.idea} ("${r.risingSearch}" ${r.growth})`).join('\n')
    : n.mode === 'report' ? n.rows.slice(0, 5).map((r, i) => `${i + 1}. ${r.risingSearch} (${r.growth})`).join('\n') : '';
  const k = n.keywords || {};
  const keep = n.source === 'sheet' && k.suggested?.length ? ' Add the ones you like to your sheet to keep them.' : '';
  // topics that brought (almost) nothing: worth replacing with more concrete ones
  const weak = (k.used || []).filter(w => !(k.noData || []).includes(w) && ((k.yield || {})[w] || 0) <= 1);
  const weakNote = weak.length && weak.length < (k.used || []).length ? `\nTopics that found little this time: ${weak.join(', ')}.` : '';
  return `${n.summary}${keep}${weakNote}${n.keywordNote ? `\n${n.keywordNote}` : ''}${top ? `\n${top}` : ''}`;
});
const skipped = niches[0]?.skippedRows?.length ? `\n\nSkipped these sheet rows because they have no niche: ${niches[0].skippedRows.join(', ')}.` : '';
return [{ json: { text: `What's rising in your niches this week\n\n${blocks.join('\n\n')}${skipped}` } }];
